  console.log('%s | beat=%-12s current=%-8s active=%-8s -> runtime=%-8s boot=%-8s %s',
    label.padEnd(26), beat, cw, apid, runtime, boot,
    runtime === cw ? 'STABLE' : '*** SWAP BACK TO ' + runtime + ' ***');
}

