 * the body keeps that clearance and simply finishes the walk. With no handoff
 * the snapped waypoint is returned untouched.
 */
export function applyTerminalExactGoal(
  waypoint: THREE.Vector3,
  goal: THREE.Vector3,
  up: THREE.Vector3,
  handoff: boolean
