export function commitSystemBodyTarget(address: PlanetAddress): number {
  const normalized = normalizePlanetAddress(address);
  if (coordinateKey(normalized.system) !== snapshot.systemId) {
    throw new Error('System-body target must belong to the current star system.');
  }
  const activationEpoch = snapshot.activationEpoch + 1;
  const target = freezeTarget({
    kind: 'system_body',
    address: normalized,
    worldId: planetWorldId(normalized)
  });
  publishBoundary({ ...snapshot, target, activationEpoch });
  return activationEpoch;
}

/**
 * Aim at a station in this system.
 *
 * Same shape and same epoch discipline as a planet target, so preparation started
 * against a stale epoch is discarded identically. What it does *not* do is claim
 * the pose-writer lease or touch `activePlanetId` — flying to a station changes
 * nothing about which world the player is resident on, and an spaceStation that
 * quietly evicted the active planet would strand terrain that is still loaded.
 */
export function commitSpaceStationTarget(address: SpaceStationAddress): number {
  const normalized = normalizeSpaceStationAddress(address);
  if (coordinateKey(normalized.system) !== snapshot.systemId) {
    throw new Error('SpaceStation target must belong to the current star system.');
  }
  // The story fence. Aiming at a station is a thing the player earns by asking
  // for it: in story worlds the bearing must have been claimed first. Sandbox
  // membership is tested inside the predicate, so `?spacestation=` is
  // unaffected. A refused commit is a NO-OP, never a throw — the caller is the
  // shipped approach driver and a fence is not an error condition.
  if (!spaceStationTargetingAuthorized()) return snapshot.activationEpoch;
  const activationEpoch = snapshot.activationEpoch + 1;
  const target = freezeTarget({
    kind: 'space_station',
    address: normalized,
    worldId: spaceStationWorldId(normalized)
  });
  publishBoundary({ ...snapshot, target, activationEpoch });
  return activationEpoch;
}

export function commitInterstellarTarget(coordinate: SystemCoordinate): number {
  const normalized = normalizeCoordinate(coordinate);
  if (coordinateKey(normalized) === snapshot.systemId) {
    throw new Error('Interstellar target must identify a different star system.');
  }
  const activationEpoch = snapshot.activationEpoch + 1;
  const target = freezeTarget({
    kind: 'star_system',
    coordinate: normalized,
    systemId: coordinateKey(normalized)
  });
  publishBoundary({ ...snapshot, target, activationEpoch });
  return activationEpoch;
}

